import{_ as a,o as e,c as t,ak as l,ar as i,al as d}from"./chunks/framework.DELonZpw.js";const b=JSON.parse('{"title":"Godot 4 安装教程（Windows 2026最新版）","description":"","frontmatter":{"0":"i","1":"n","2":"d","3":"e","4":"x","5":":","6":"0"},"headers":[],"relativePath":"godot/godot-4-installation.md","filePath":"godot/godot-4-installation.md","lastUpdated":1780925078000}'),r={name:"godot/godot-4-installation.md"};function n(s,o,h,c,p,g){return e(),t("div",null,[...o[0]||(o[0]=[l('<h1 id="godot-4-安装教程-windows-2026最新版" tabindex="-1">Godot 4 安装教程（Windows 2026最新版） <a class="header-anchor" href="#godot-4-安装教程-windows-2026最新版" aria-label="Permalink to “Godot 4 安装教程（Windows 2026最新版）”">​</a></h1><p>本教程适用于搜索以下问题的用户：</p><ul><li>Godot 4 安装教程</li><li>Godot 4 Windows 下载</li><li>如何安装 Godot 引擎</li><li>Godot 4 打不开怎么办</li></ul><p>Godot 是一款免费、开源、跨平台的游戏引擎，适合独立开发者、初学者和小团队使用。<br> 本文将以 <strong>Windows</strong> 为例，带你完成 <strong>Godot 4 下载、安装、首次启动</strong>。</p><p>官网地址：<a href="https://godotengine.org/zh-cn/" target="_blank" rel="noreferrer">https://godotengine.org/zh-cn/</a></p><h2 id="一、下载-godot-4" tabindex="-1">一、下载 Godot 4 <a class="header-anchor" href="#一、下载-godot-4" aria-label="Permalink to “一、下载 Godot 4”">​</a></h2><p>Godot 可以从多个渠道下载，建议优先使用官方渠道。</p><h3 id="_1-官方下载页" tabindex="-1">1. 官方下载页 <a class="header-anchor" href="#_1-官方下载页" aria-label="Permalink to “1. 官方下载页”">​</a></h3><ul><li>Windows 下载页：<a href="https://godotengine.org/download/windows/" target="_blank" rel="noreferrer">https://godotengine.org/download/windows/</a></li><li>官方镜像页：<a href="https://godotengine.itch.io/godot" target="_blank" rel="noreferrer">https://godotengine.itch.io/godot</a></li></ul><h3 id="_2-下载哪个版本" tabindex="-1">2. 下载哪个版本 <a class="header-anchor" href="#_2-下载哪个版本" aria-label="Permalink to “2. 下载哪个版本”">​</a></h3><p>一般情况下，Windows 用户直接下载带有以下后缀的版本即可：</p><ul><li><code>x86_64</code></li><li><code>64-bit</code></li></ul><p>如果你只想用 <strong>GDScript</strong> 开发，直接下载标准版即可。<br> 如果你需要 <strong>C#</strong> 支持，可以选择对应的 C# 版本。</p><blockquote><p>提示：如果网络环境限制导致下载不方便，可以通过社区或交流群获取帮助。</p></blockquote><h2 id="二、安装-godot" tabindex="-1">二、安装 Godot <a class="header-anchor" href="#二、安装-godot" aria-label="Permalink to “二、安装 Godot”">​</a></h2><p>Godot 的安装方式非常简单，它通常不需要传统意义上的“安装程序”。</p><h3 id="_1-解压下载包" tabindex="-1">1. 解压下载包 <a class="header-anchor" href="#_1-解压下载包" aria-label="Permalink to “1. 解压下载包”">​</a></h3><p>下载完成后，你会得到一个压缩包。<br> 解压后，通常会看到两个可执行文件：</p><ul><li><code>Godot_v4.x.x-stable_win64.exe</code></li><li><code>Godot_v4.x.x-stable_win64_console.exe</code></li></ul><h3 id="_2-启动-godot" tabindex="-1">2. 启动 Godot <a class="header-anchor" href="#_2-启动-godot" aria-label="Permalink to “2. 启动 Godot”">​</a></h3><p>一般情况下，直接双击主程序即可：</p><ul><li><code>Godot_v4.x.x-stable_win64.exe</code></li></ul><p>如果你需要查看命令行输出、调试信息或报错信息，可以运行：</p><ul><li><code>Godot_v4.x.x-stable_win64_console.exe</code></li></ul><p><img src="'+i+'" alt="Godot 4 Windows 运行程序示意图"></p><h2 id="三、第一次启动-godot" tabindex="-1">三、第一次启动 Godot <a class="header-anchor" href="#三、第一次启动-godot" aria-label="Permalink to “三、第一次启动 Godot”">​</a></h2><p>首次启动后，你会看到 Godot 的项目管理器界面。<br> 如果系统语言设置正常，界面通常会自动显示为中文。</p><p><img src="'+d+'" alt="Godot 4 Windows 首次启动界面"></p><h3 id="_1-建议使用英文目录" tabindex="-1">1. 建议使用英文目录 <a class="header-anchor" href="#_1-建议使用英文目录" aria-label="Permalink to “1. 建议使用英文目录”">​</a></h3><p>虽然 Godot 支持中文路径，但创建项目时，建议尽量把项目放在 <strong>英文路径清晰</strong> 的目录下。<br> 这样可以减少某些路径识别问题，尤其是在导出、插件或第三方工具配合使用时更稳妥。</p><h3 id="_2-认识项目管理器" tabindex="-1">2. 认识项目管理器 <a class="header-anchor" href="#_2-认识项目管理器" aria-label="Permalink to “2. 认识项目管理器”">​</a></h3><p>你会在这里看到：</p><ul><li>新建项目</li><li>导入项目</li><li>最近打开的项目</li></ul><p>对于新手来说，先认识这个界面就够了，下一篇再正式创建项目。</p><h2 id="四、常见问题" tabindex="-1">四、常见问题 <a class="header-anchor" href="#四、常见问题" aria-label="Permalink to “四、常见问题”">​</a></h2><h3 id="_1-godot-打不开怎么办" tabindex="-1">1. Godot 打不开怎么办？ <a class="header-anchor" href="#_1-godot-打不开怎么办" aria-label="Permalink to “1. Godot 打不开怎么办？”">​</a></h3><p>可以先检查以下几点：</p><ul><li>是否下载了正确的 Windows 版本</li><li>文件是否被压缩包完整解压</li><li>系统是否缺少运行环境</li><li>是否误点了 console 版本并误以为程序没反应</li></ul><h3 id="_2-为什么项目路径最好不要太复杂" tabindex="-1">2. 为什么项目路径最好不要太复杂？ <a class="header-anchor" href="#_2-为什么项目路径最好不要太复杂" aria-label="Permalink to “2. 为什么项目路径最好不要太复杂？”">​</a></h3><p>路径过长、包含特殊符号、空格过多，偶尔会引起一些兼容问题。<br> 新手阶段建议尽量使用简单路径。</p><h3 id="_3-godot-需要安装吗" tabindex="-1">3. Godot 需要安装吗？ <a class="header-anchor" href="#_3-godot-需要安装吗" aria-label="Permalink to “3. Godot 需要安装吗？”">​</a></h3><p>大多数情况下不需要。<br> Godot 的 Windows 版本通常是 <strong>解压即用</strong>。</p><h3 id="_4-godot-支持-c-吗" tabindex="-1">4. Godot 支持 C# 吗？ <a class="header-anchor" href="#_4-godot-支持-c-吗" aria-label="Permalink to “4. Godot 支持 C# 吗？”">​</a></h3><p>支持。<br> 如果你想用 C# 开发，请下载带有 C# 支持的版本。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>Godot 4 的安装并不复杂，Windows 用户一般只要做到这几步就够了：</p><ol><li>下载官方版本</li><li>解压压缩包</li><li>运行主程序</li><li>首次启动并进入项目管理器</li></ol><p>如果你已经完成这一步，下一篇就可以继续学习如何创建第一个项目。</p>',48)])])}const G=a(r,[["render",n]]);export{b as __pageData,G as default};
